def apakah_independen_joint(joint):
    px = {}
    py = {}
    for (x, y), p in joint.items():
        px[x] = px.get(x, 0) + p
        py[y] = py.get(y, 0) + p
    return all(abs(joint.get((x, y), 0) - px[x] * py[y]) < 1e-9 for x in px for y in py)

